// Water and ground use matching tiles: no overlapping giant faces or hidden pool surfaces.
function waterArea(){if(save.map==='Christmas Village')return{x0:0,x1:0,z0:0,z1:0};return save.map==='Splash Park'?{x0:-16,x1:-6,z0:-14,z1:0}:save.map==='Grand Meow Hotel'?{x0:8,x1:14,z0:-6,z1:6}:{x0:-60,x1:-48,z0:-60,z1:60}}
function inWater(x,z){const a=waterArea();return x>a.x0&&x<a.x1&&z>a.z0&&z<a.z1}
function drawGroundAndWater(map){if(buildingWorld)return;if(save.graphics==='fast'){const a=waterArea();for(const [x0,x1,z0,z1,wet] of [[-MAP_HALF,a.x0,-MAP_HALF,MAP_HALF,false],[a.x1,MAP_HALF,-MAP_HALF,MAP_HALF,false],[a.x0,a.x1,-MAP_HALF,a.z0,false],[a.x0,a.x1,a.z1,MAP_HALF,false],[a.x0,a.x1,a.z0,a.z1,true]]){if(x0===x1||z0===z1)continue;for(let x=x0;x<x1;x+=8)for(let z=z0;z<z1;z+=8){const xx=Math.min(x+8,x1),zz=Math.min(z+8,z1);if(!visibleSphere((x+xx)/2,-.05,(z+zz)/2,6))continue;poly([[x,-.05,z],[xx,-.05,z],[xx,-.05,zz],[x,-.05,zz]],wet?'#337b88':map.floor,wet?3:4)}}return}const tile=2;for(let x=-MAP_HALF;x<MAP_HALF;x+=tile)for(let z=-MAP_HALF;z<MAP_HALF;z+=tile){if(!visibleSphere(x+1,-.05,z+1,1.5))continue;const wet=inWater(x+1,z+1),shade=groundShade(x+1,z+1);poly([[x,-.05,z],[x+tile,-.05,z],[x+tile,-.05,z+tile],[x,-.05,z+tile]],furShade(wet?'#337b88':map.floor,shade),wet?3:4)}}

function poolRim(x0,x1,z0,z1){const w=x1-x0,d=z1-z0;box(x0-.18,0,(z0+z1)/2,.36,.2,d+.72,'#f0edda');box(x1+.18,0,(z0+z1)/2,.36,.2,d+.72,'#f0edda');box((x0+x1)/2,0,z0-.18,w,.2,.36,'#f0edda');box((x0+x1)/2,0,z1+.18,w,.2,.36,'#f0edda')}
function resetHealthPacks(){ensureWorld();healthPacks=[];const anchors=[[0,4],[-17,8],[17,6],[-5,19],[5,-20],[-39,30],[39,30],[-39,-30],[39,-30],[0,49],[0,-49],[-43,0],[43,0]];for(const [ax,az] of anchors){let spot=null;for(let r=0;r<8&&!spot;r++)for(let i=0;i<12&&!spot;i++){const a=i*Math.PI/6,x=ax+Math.cos(a)*r,z=az+Math.sin(a)*r;if(Math.abs(x)<PLAY_LIMIT-1&&Math.abs(z)<PLAY_LIMIT-1&&!inWater(x,z)&&!solids.some(c=>overlaps(x,0,z,c))&&healthPacks.every(p=>Math.hypot(p.x-x,p.z-z)>3))spot={x,y:0,z,cooldown:0}}if(spot)healthPacks.push(spot)}}
function updateHealthPacks(dt){for(const p of healthPacks){if(p.cooldown>0){p.cooldown=Math.max(0,p.cooldown-dt);continue}if(health>=100||player.y>1.1||Math.hypot(player.x-p.x,player.z-p.z)>1.05)continue;const dx=p.x-player.x,dz=p.z-player.z,d=Math.hypot(dx,dz);if(d>.001&&solids.some(c=>{const hit=rayBox({x:player.x,y:.6,z:player.z},{x:dx/d,y:0,z:dz/d},c.min,c.max);return hit!==null&&hit<d}))continue;const gained=Math.min(HEAL_AMOUNT,100-health);health+=gained;p.cooldown=PACK_RESPAWN;syncHud();toast('HEALED! +'+gained+' health');burst({...p,color:'#b5ff9d'},10)}}
function drawHealthPacks(){for(const p of healthPacks){if(p.cooldown>0)continue;const y=.22+Math.sin(t*2+p.x)*.09;box(p.x,y,p.z,.95,.65,.7,'#71dd91');box(p.x,y+.18,p.z-.36,.55,.16,.035,'#ffffff');box(p.x,y+.07,p.z-.38,.16,.40,.035,'#ffffff');box(p.x,y+.18,p.z+.36,.55,.16,.035,'#ffffff');box(p.x,y+.07,p.z+.38,.16,.40,.035,'#ffffff');box(p.x,y+.65,p.z,.6,.035,.16,'#ffffff');box(p.x,y+.66,p.z,.16,.035,.5,'#ffffff')}}

// Three-sided shelters have an open entrance, opaque cover, and a jumpable roof.
function drawHideouts(){const color=save.map==='Grand Meow Hotel'?'#ba8f80':save.map==='Boardwalk Beach'?'#82b7ca':'#79baa0';for(const [x,z] of [[-18,7],[17,16],[3,-20],[-40,36],[40,36],[-40,-36],[40,-36],[0,46]]){box(x-1.9,0,z,.35,2.7,3.8,color);box(x+1.9,0,z,.35,2.7,3.8,color);box(x,0,z-1.75,3.8,2.7,.35,color);box(x,2.7,z,4.2,.25,4.2,'#e5d9b3');box(x-1,0,z+3.1,1.1,.7,1.1,'#caa67e')}for(const [x,z] of [[-4,8],[9,16]])box(x,0,z,2,1.6,2,'#cba77a')}

// Outer districts make the larger arena useful: lanes, cover, raised terraces, and landmarks.
function drawOuterDistricts(){const hotel=save.map==='Grand Meow Hotel',beach=save.map==='Boardwalk Beach';for(const [x,z] of [[-33,-30],[33,-30],[-33,30],[33,30]]){const wall=hotel?'#dfbea0':beach?'#82bcc8':'#87c5b0';box(x,0,z,9,.5,8,'#e7d8b7');box(x-4.3,.5,z,.45,3.4,8,wall);box(x+4.3,.5,z,.45,3.4,8,wall);box(x,.5,z-3.8,8.6,3.4,.4,wall);box(x,3.9,z,10,.35,9,hotel?'#b78e7d':'#ecd393');for(let i=0;i<7;i++)box(x+6,0,z+5-i,2,(i+1)*.6,1,'#d1ba96');box(x-1,.5,z-2,2,.8,1,'#b99b7b');if(hotel){for(let w=-3;w<=3;w+=3)box(x+w,1.7,z-3.55,1.4,1.2,.08,'#6699b3')}else{box(x,4.25,z,2,.15,2,'#f5eee0')}}for(const [x,z] of [[-20,35],[20,35],[-20,-35],[20,-35],[-38,12],[38,12],[-38,-12],[38,-12]]){box(x,0,z,3,1.5,3,'#c8aa81');box(x+4,0,z+2,2,2.5,2,'#a8bc99')}for(const z of [-52,52]){box(0,0,z,18,.35,5,'#dbc8a2');for(const x of [-7,7])box(x,.35,z,.35,3,.35,'#b8956d');box(0,3.35,z,17,.35,4,'#e5b58e')}for(const x of [-59,59])box(x,0,0,.25,1.2,118,'#a6bfa3');for(const z of [-59,59])box(0,0,z,118,1.2,.25,'#a6bfa3')}

function scenery(){if(save.map==='Christmas Village'){drawChristmasVillage();return}drawMapDetails();drawOuterDistricts();drawHideouts();let map=maps.find(m=>m.name===save.map)||maps[0];drawGroundAndWater(map);if(save.map==='Splash Park'){poolRim(-16,-6,-14,0);for(let i=0;i<9;i++)box(-15+i*.62,3.9-i*.43,-13,1.6,.25,2,'#f1bb6d');box(-15,0,-13,.3,4,2,'#dce7d9');box(12,.01,-12,6,.2,7,'#e8e1bc');box(12,3,-12,7,.3,8,'#f3ad9e');for(let i=0;i<6;i++)box(7.5,.0,-5-i*1.1,2,(i+1)*.5,1.1,'#ead6b1');for(let x of [9.5,14.5])for(let z of [-15,-9])box(x,0,z,.18,3,.18,'#e3dbbf');for(let i=0;i<4;i++){box(-15+i*3,0,15,1.8,.3,3,'#f6dd94');box(-15+i*3,.3,16,1.8,.8,.25,'#f6dd94')}}else if(save.map==='Grand Meow Hotel'){box(0,0,-18,28,8,3,'#e4c7aa');for(let x=-12;x<=12;x+=3)for(let y=1;y<8;y+=2)box(x,y,-16.45,1.4,1.2,.1,'#596e84');box(0,0,-16,4,3,.2,'#394e61');box(0,3.2,-14.9,6,.25,3,'#b88078');for(let i=0;i<6;i++)box(-4.2,0,-8-i*1.05,2,(i+1)*.55,1.05,'#d8ba9b');poolRim(8,14,-6,6);for(let x of [-13,-6,6,13]){box(x,0,13,2,.5,2,'#eed4a5');box(x,.5,13,.2,2,.2,'#e5d5bb');box(x-0.1,2.5,13,4,.2,4,'#d58c84')}}else{for(let i=0;i<4;i++){box(-10+i*7,0,-14,4,3,4,colors[i]);box(-10+i*7,3,-14,5,.4,5,'#eddcaa');box(-10+i*7,0,-11.95,1,2,.1,'#425e67')}for(let x of [-12,0,12]){box(x,0,10,.2,3,.2,'#ebd8ad');box(x,3,10,5,.25,5,'#f0b3a2')}}for(let x of [-59,59])for(let z of [-55,-35,-15,5,25,45]){box(x,0,z,.6,3,.6,'#a29172');box(x,2.7,z,3,2.5,3,'#719c7d')}}
function draw(){updateChaseHud();$('spotNotice').hidden=mode!=='play'||t>=noticeUntil;let playing=mode!=='lobby';if(playing){camera={x:player.x,y:player.y+1.8,z:player.z,yaw:player.yaw,pitch:player.pitch}}else camera={x:25,y:21,z:32,yaw:.54,pitch:.47};const map=maps.find(m=>m.name===save.map)||maps[0];drawDaylight(map);faces=[];ensureWorld();scenery();drawContactShadows();if(playing)drawHealthPacks();bots.forEach(b=>cat(b,mode==='lobby'?1.55:1));particles.forEach(p=>box(p.x,p.y,p.z,.15,.15,.15,p.color));if(!sceneRenderer)faces.sort((a,b)=>b.d-a.d);ctx.save();if(shake)ctx.translate((Math.random()-.5)*8,(Math.random()-.5)*8);if(sceneRenderer){sceneRenderer(faces,W,H);ctx.drawImage(sceneRenderer.surface,0,0,W,H)}else for(const f of faces){ctx.beginPath();f.p.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle='#132a3320';ctx.lineWidth=.5;ctx.stroke()}for(const tr of tracers){let a=project(tr.a.x,tr.a.y,tr.a.z),b=project(tr.b.x,tr.b.y,tr.b.z);if(a&&b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=tr.color;ctx.lineWidth=3;ctx.stroke()}}if(playing)for(const b of bots){if(b.respawn)continue;let p=project(b.x,b.y+3,b.z);if(p){ctx.fillStyle='#182c35';ctx.fillRect(p.x-19,p.y,38,4);ctx.fillStyle='#ffb4ac';ctx.fillRect(p.x-19,p.y,38*b.hp/100,4);if(b.aware&&hasLineOfSight(player,b)){ctx.font='bold 24px Arial';ctx.textAlign='center';ctx.fillStyle=b.unseen>.1?'#f1c86c':'#ff585e';ctx.fillText(b.unseen>.1?'?':'!',p.x,p.y-10)}}}ctx.restore();if(save.map==='Christmas Village')drawSnowfall();if(playing){drawDamageNumbers();drawHeldGun();$('crosshair').style.left='50%';$('crosshair').style.top='50%';$('crosshair').textContent=hitFlash>0?'×':'';$('crosshair').style.color=hitFlash>0?(lastHeadshot?'#ffd35a':'#ff704f'):'#ffffff';}}
