// Conservative view-volume rejection avoids building offscreen meshes and floor tiles.
function visibleSphere(x,y,z,r){const dx=x-camera.x,dy=y-camera.y,dz=z-camera.z,cy=Math.cos(camera.yaw),sy=Math.sin(camera.yaw),cp=Math.cos(camera.pitch),sp=Math.sin(camera.pitch),horizontal=dx*cy-dz*sy,forward=-dx*sy-dz*cy,vertical=dy*cp+forward*sp,depth=forward*cp-dy*sp,f=Math.min(W,H)*1.05;return depth+r>.2&&Math.abs(horizontal)<Math.max(depth,0)*W/(2*f)+r*2&&Math.abs(vertical)<Math.max(depth,0)*H/(2*f)+r*2}

