function drawSnowfall(){ctx.save();ctx.fillStyle='#ffffff';const count=save.graphics==='fast'?32:64;for(let i=0;i<count;i++){const depth=1+(i%4),x=((i*137.51+Math.sin(t*.35+i)*18-camera.yaw*110/depth)%(W+40)+W+40)%(W+40)-20,y=(i*89.7+t*(12+20/depth))%(H+20)-10;ctx.globalAlpha=.3+.13*(4-depth);ctx.beginPath();ctx.arc(x,y,depth===1?2:1,0,Math.PI*2);ctx.fill()}ctx.restore()}

function catAwareness(b,dt){
 const dx=player.x-b.x,dz=player.z-b.z,d=Math.hypot(dx,dz),facing=d<.001?1:(-Math.sin(b.yaw)*dx-Math.cos(b.yaw)*dz)/d;
 const visible=d<24&&(b.aware||d<3||facing>.5)&&hasLineOfSight(b,player);
 if(visible){b.aware=true;b.unseen=0;b.lastSeenX=player.x;b.lastSeenZ=player.z}
 else if(b.aware){b.unseen+=dt;if(b.unseen>=3){b.aware=false;b.shot=difficulty().delay}}
 return visible;
}
function updatePursuit(){const active=bots.some(b=>b.aware&&!b.respawn&&b.hp>0);if(active!==pursuitActive){const notice=$('spotNotice');notice.textContent=active?'SPOTTED':'✓';notice.className=active?'spotted':'escaped';notice.setAttribute?.('aria-label',active?'Spotted by a cat':'You lost the cats');noticeUntil=t+5;pursuitActive=active}}

function sprintSpeed(dt,moving){const held=keys.has('ShiftLeft')||keys.has('ShiftRight');if(sprintExhausted&&stamina>=25)sprintExhausted=false;const sprint=moving&&held&&!sprintExhausted&&stamina>0;if(sprint){stamina=Math.max(0,stamina-dt*25);if(!stamina)sprintExhausted=true}else stamina=Math.min(100,stamina+dt*18);return sprint?12:8}
function updateChaseHud(){const playing=mode==='play';$('staminaHud').hidden=!playing;$('staminaFill').style.width=stamina+'%';$('staminaLabel').textContent=sprintExhausted?'CATCH YOUR BREATH':'SHIFT · SPRINT';const chasing=bots.filter(b=>b.aware&&!b.respawn&&b.hp>0);$('chaseHud').hidden=!playing||!chasing.length;if(!chasing.length)return;const unseen=Math.min(...chasing.map(b=>b.unseen||0)),hiding=unseen>.1;$('chaseLabel').textContent=hiding?'LOSING THEM…':chasing.length+' CAT'+(chasing.length===1?'':'S')+' CHASING';$('escapeFill').style.width=Math.min(100,unseen/3*100)+'%';$('chaseHint').textContent=hiding?'Stay hidden to escape':'Break their line of sight';}
